   "file": "01-minikube-pod.md",
   "ten": "Cài Minikube và chạy Pod đầu tiên",
   "goc": "https://devops.vn/posts/kubernetes-co-ban-cai-dat-minikube/",
   "thoiGian": "25 phút",
